def mass_label(value: float) -> str:
    text = f"{value:.4f}".rstrip("0").rstrip(".")
    return text


def main() -> None:
    elements = []
    for row in ROWS:
        (z, symbol, name, mass, group, period, category, config, state, mp, bp, ox, en, dens, year, who, block, occ) = row
        elements.append({
            "atomicNumber": z,
            "symbol": symbol,
            "name": name,
            "atomicMass": mass,
            "atomicMassLabel": mass_label(mass),
            "group": group,
            "period": period,
            "category": category,
            "electronConfiguration": config,
            "state": state,
            "meltingPointC": mp,
            "boilingPointC": bp,
            "oxidationStates": ox,
            "electronegativity": en,
            "density": dens,
            "discoveryYear": year,
            "discoverer": who,
            "block": block,
            "occurrence": occ,
        })
    out = Path(__file__).resolve().parents[1] / "data" / "periodic_table.json"
    out.write_text(json.dumps({"elements": elements}, indent=2) + "\n")
    print(f"wrote {len(elements)} elements to {out}")


if __name__ == "__main__":
    main()
